from collections import deque
def regions(g):
    bg=8
    seen=set(); comps=[]
    H,W=len(g),len(g[0])
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and (i,j) not in seen:
                q=deque([(i,j)]); seen.add((i,j)); cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=y+dy,x+dx
                        if 0<=a<H and 0<=b<W and g[a][b]!=bg and (a,b) not in seen:
                            seen.add((a,b)); q.append((a,b))
                comps.append(cells)
    return comps

def transform(g):
    g=[r[:] for r in g]; H,W=len(g),len(g[0])
    for cells in regions(g):
        ys=[c[0] for c in cells]; xs=[c[1] for c in cells]
        pts=[(y,x) for y,x in cells if g[y][x]!=0]
        if not pts: continue
        # bbox of nonzero cluster
        py0,pz=min(p[0] for p in pts); py1=max(p[0] for p in pts)
        px0=min(p[1] for p in pts); px1=max(p[1] for p in pts)
        ph,pw=py1-py0+1,px1-px0+1
        P=[row[px0:px1+1] for row in g[py0:py1+1]]
        for y in range(min(ys),max(ys)+1):
            for x in range(min(xs),max(xs)+1):
                g[y][x]=P[(y-py0)%ph][(x-px0)%pw]
    return g

